@@ constants & addresses
.equ WIDTH, 320							// screen width in pixels
.equ HEIGHT, 240						// screen height in pixels
.equ BYTES_PER_ROW, 10					// 2^10 = 1024 bytes per row
/* explanation: each pixel = 2 bytes, 320 pixels per row = 640 bytes per row. */
/* explanation (con't): 2^9 = 512 bytes (not enough). 2^10 = 1024 (yay) */
.equ BYTES_PER_PIXEL, 1					// 2^1 = 2 bytes per pixel (rgb565)
.equ PIXBUF, 0xc8000000					// base address of vga pixel buffer

.global _start
_start:
	ldr sp, =0x800000					// initial stack pointer for subroutines
    mov r8, #0							// index (for multiple images if needed)
	
loop:
	/* the following will always be true as long as we're working with one image */
	cmp r8, #0							// check current state
	ldreq r0, =list						// if 0, load pointer to image data (list)
    bl fill_colour						// fill screen w image
       
    b loop								// infinite loop to keep image on screen

fill_colour:
	push {r8, r9, r10, lr}				// save some registers
    
    mov r10, r0							// r10 = pointer to pixel data array
	mov r9,#0							// r9 = y-coordinate counter (row)
	mov r8,#0							// r8 = x-coordinate counter (column)
	
	/* two loops to draw each pixel (2D array implementation) */
    1:	mov r8,#0						// reset x-counter for each new row
        2:  mov r0, r8					// prepare r0 = x for write_pixel
            mov r1, r9					// prepare r1 = y for write_pixel
            ldr r2, [r10]				// load 16-bit color value from memory
            bl write_pixel				// call pixel-drawing subroutine
			add r10,r10,#4				// move to next color in data
            add r8,r8,#1				// increment x
			cmp r8,#320					// have we reached the end of the row?
            bne 2b						// loop if not
		add r9,r9,#1					// increment y
        cmp r9,#240						// check if all rows are drawn
        bne 1b							// loop if y < 240

	pop {r8, r9, r10, lr} 				// bring back original register values
    bx lr 								// return to loop

write_pixel:
	/* address = base + (y << 10) + (x << 1) */
    lsl r1, r1, #BYTES_PER_ROW			// shift y-coord to get row offset
    lsl r0, r0, #BYTES_PER_PIXEL		// shift x-coord to get pixel offset
    add r1, r0							// combine x and y offsets
    ldr r0, =PIXBUF						// load vga base address
    
    strh r2, [r0,r1] 					// this is where pixel is written 
    bx lr 								// return to fill_color
	

